// Copies the STRX Animation IntelliSense language logic into the docs site,
// so the editor page's demos run the extension's real completion, hover,
// diagnostics, and preview code in the browser.
//
// Usage: node scripts/sync-editor-extension.mjs ../strx-animation-intellisense
// (build the extension first with `npm run compile` there).

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const extension = path.resolve(process.argv[2] ?? '../strx-animation-intellisense');
const out = path.join(extension, 'out');
const version = JSON.parse(fs.readFileSync(path.join(extension, 'package.json'), 'utf8')).version;
const modules = ['grammar', 'completion', 'preview', 'hover'];

const parts = modules.map(name => {
  const source = fs
    .readFileSync(path.join(out, `${name}.js`), 'utf8')
    .replace(/^\/\/# sourceMappingURL=.*$/m, '')
    .trim();
  return `define(${JSON.stringify(name)}, function (exports, require) {\n${source}\n});`;
});

const bundle = `/*
 * Language logic from STRX Animation IntelliSense ${version}
 * (https://github.com/wangjagom/strx-animation-intellisense), MIT license.
 * Generated by scripts/sync-editor-extension.mjs; do not edit by hand.
 */
(function (root) {
  'use strict';

  var modules = {};
  var Buffer = {
    from: function (text) {
      return {
        toString: function () {
          return btoa(unescape(encodeURIComponent(text)));
        },
      };
    },
  };

  function require(name) {
    return modules[name.replace('./', '')];
  }

  function define(name, factory) {
    var exports = (modules[name] = {});
    factory(exports, require);
  }

${parts.join('\n\n')}

  root.StrxEditorExtension = {
    version: ${JSON.stringify(version)},
    analyze: modules.grammar.analyze,
    computeCompletions: modules.completion.computeCompletions,
    computeHover: modules.hover.computeHover,
    tokenPreviewSvg: modules.preview.tokenPreviewSvg,
  };
})(typeof globalThis !== 'undefined' ? globalThis : this);
`;

const target = path.join(ROOT, 'website/static/editor-extension.js');
fs.writeFileSync(target, bundle);
console.log(`Wrote ${path.relative(ROOT, target)} from STRX Animation IntelliSense ${version}.`);
